package app.fta.android;
import android.app.*;import android.content.*;import android.database.Cursor;import android.graphics.*;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import org.json.*;import java.io.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;
// Real scoped MediaStore and decoder checks use only generated test pictures and remove only their returned URIs.
final class GalleryChecks {
 private final Instrumentation test;private int checks;GalleryChecks(Instrumentation value){test=value;}
 private void check(boolean value,String name){if(!value)throw new AssertionError(name);checks++;}
 private byte[] bytes(InputStream input)throws Exception{try(input;ByteArrayOutputStream output=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=input.read(buffer))!=-1)output.write(buffer,0,n);return output.toByteArray();}}
 private void image(File path,Bitmap.CompressFormat format)throws Exception{Bitmap bitmap=Bitmap.createBitmap(96,64,Bitmap.Config.ARGB_8888);bitmap.eraseColor(0xFF24466B);try(FileOutputStream output=new FileOutputStream(path)){check(bitmap.compress(format,95,output),"generated image");}bitmap.recycle();}
 private int pending(Context c)throws Exception{try(Cursor rows=c.getContentResolver().query(MediaStore.setIncludePending(MediaStore.Images.Media.getContentUri(MediaStore.VOLUME_EXTERNAL_PRIMARY)),new String[]{MediaStore.MediaColumns._ID},MediaStore.MediaColumns.IS_PENDING+"=1 AND "+MediaStore.MediaColumns.OWNER_PACKAGE_NAME+"=?",new String[]{c.getPackageName()},null)){return rows==null?0:rows.getCount();}}
 void run(){Bundle result=new Bundle();int resultCode=Activity.RESULT_CANCELED;ArrayList<Uri> created=new ArrayList<>();ArrayList<File> files=new ArrayList<>();try{
  Context context=test.getTargetContext();NativeBridge.initialize(context);GalleryExport.recover(context);
  String prefix="FTA-gallery-check-"+UUID.randomUUID();File png=new File(NativeBridge.received,prefix+".png"),jpg=new File(NativeBridge.received,prefix+".jpg");files.add(png);files.add(jpg);image(png,Bitmap.CompressFormat.PNG);image(jpg,Bitmap.CompressFormat.JPEG);
  GalleryExport.Photo p=GalleryExport.verified(NativeBridge.received,png.getName()),j=GalleryExport.verified(NativeBridge.received,jpg.getName());check(p!=null&&"image/png".equals(p.mime),"PNG content decoded");check(j!=null&&"image/jpeg".equals(j.mime),"JPEG content decoded");
  File spoof=new File(NativeBridge.received,prefix+"-spoof.jpg");files.add(spoof);java.nio.file.Files.copy(png.toPath(),spoof.toPath());check(GalleryExport.verified(NativeBridge.received,spoof.getName())==null,"MIME extension mismatch rejected");
  File truncated=new File(NativeBridge.received,prefix+"-truncated.png");files.add(truncated);try(FileOutputStream output=new FileOutputStream(truncated)){output.write(java.util.Arrays.copyOf(bytes(new FileInputStream(png)),40));}check(GalleryExport.verified(NativeBridge.received,truncated.getName())==null,"truncated image rejected");
  check(GalleryExport.verified(NativeBridge.received,"../identity.json")==null,"path escape rejected");File link=new File(NativeBridge.received,prefix+"-link.png");files.add(link);java.nio.file.Files.createSymbolicLink(link.toPath(),png.toPath());check(GalleryExport.verified(NativeBridge.received,link.getName())==null,"symlink rejected");
  JSONObject record=new JSONObject().put("direction","receive").put("state","completed").put("kind","files").put("items",new JSONArray().put(new JSONObject().put("state","completed").put("saved_name",png.getName())));check(GalleryExport.candidates(record).size()==1,"final incoming photo eligible");record.put("state","receiving");check(GalleryExport.candidates(record).isEmpty(),"incomplete receive excluded");record.put("state","completed").put("direction","send");check(GalleryExport.candidates(record).isEmpty(),"outbound excluded");
  int initialPending=pending(context);GalleryExport.Result saved=GalleryExport.save(context,Arrays.asList(p,j),new AtomicBoolean(),(a,b)->{});check(saved.saved==2&&saved.failed==0&&!saved.cancelled,"two actual MediaStore copies published");created.add(saved.first);
  check(Arrays.equals(bytes(new FileInputStream(png)),bytes(context.getContentResolver().openInputStream(saved.first))),"published PNG bytes exact");
  try(Cursor row=context.getContentResolver().query(saved.first,new String[]{MediaStore.MediaColumns.IS_PENDING,MediaStore.MediaColumns.RELATIVE_PATH},null,null,null)){check(row!=null&&row.moveToFirst()&&row.getInt(0)==0,"published row visible");check(row.getString(1).equals(Environment.DIRECTORY_PICTURES+"/FTA/"),"native Pictures album");}
  // Find only this run's second synthetic image for cleanup, never enumerate or delete unrelated gallery rows.
  try(Cursor row=context.getContentResolver().query(MediaStore.Images.Media.getContentUri(MediaStore.VOLUME_EXTERNAL_PRIMARY),new String[]{MediaStore.MediaColumns._ID},MediaStore.MediaColumns.DISPLAY_NAME+"=?",new String[]{jpg.getName()},null)){if(row!=null&&row.moveToFirst())created.add(ContentUris.withAppendedId(MediaStore.Images.Media.getContentUri(MediaStore.VOLUME_EXTERNAL_PRIMARY),row.getLong(0)));}
  GalleryExport.Result duplicate=GalleryExport.save(context,List.of(p),new AtomicBoolean(),(a,b)->{});created.add(duplicate.first);check(duplicate.saved==1&&!duplicate.first.equals(saved.first),"name collision creates separate URI");check(Arrays.equals(bytes(new FileInputStream(png)),bytes(context.getContentResolver().openInputStream(saved.first))),"previous gallery image unchanged");
  GalleryExport.Result early=GalleryExport.save(context,List.of(p),new AtomicBoolean(true),(a,b)->{});check(early.cancelled&&early.saved==0,"cancel before insertion");AtomicBoolean cancel=new AtomicBoolean();GalleryExport.Result midway=GalleryExport.save(context,List.of(p),cancel,(a,b)->cancel.set(true));check(midway.cancelled&&midway.saved==0&&pending(context)==initialPending,"cancel cleans unpublished copy");
  File missing=new File(NativeBridge.received,prefix+"-missing.png");GalleryExport.Result partial=GalleryExport.save(context,Arrays.asList(p,new GalleryExport.Photo(missing,"image/png")),new AtomicBoolean(),(a,b)->{});created.add(partial.first);check(partial.saved==1&&partial.failed==1,"partial result remains explicit");
  ContentValues abandoned=new ContentValues();abandoned.put(MediaStore.MediaColumns.DISPLAY_NAME,prefix+"-pending.png");abandoned.put(MediaStore.MediaColumns.MIME_TYPE,"image/png");abandoned.put(MediaStore.MediaColumns.RELATIVE_PATH,Environment.DIRECTORY_PICTURES+"/FTA");abandoned.put(MediaStore.MediaColumns.IS_PENDING,1);Uri pendingUri=context.getContentResolver().insert(MediaStore.Images.Media.getContentUri(MediaStore.VOLUME_EXTERNAL_PRIMARY),abandoned);check(pendingUri!=null,"abandoned row created");created.add(pendingUri);GalleryExport.recover(context);try(Cursor row=context.getContentResolver().query(pendingUri,new String[]{MediaStore.MediaColumns._ID},null,null,null)){check(row==null||row.getCount()==0,"unjournaled crash row recovered");}check(Arrays.equals(bytes(new FileInputStream(png)),bytes(context.getContentResolver().openInputStream(saved.first))),"recovery preserves published image");check(png.isFile()&&jpg.isFile(),"received originals retained");
  // An isolated provider delegates real row management but returns a read-only FD, exercising a genuine write IOException.
  ContentResolver real=context.getContentResolver();ContentProvider broken=new ContentProvider(){public boolean onCreate(){return true;}public Cursor query(Uri u,String[] p,String q,String[] a,String sort){return real.query(u,p,q,a,sort);}public String getType(Uri u){return real.getType(u);}public Uri insert(Uri u,ContentValues v){return real.insert(u,v);}public int delete(Uri u,String q,String[] a){return real.delete(u,q,a);}public int update(Uri u,ContentValues v,String q,String[] a){return real.update(u,v,q,a);}public ParcelFileDescriptor openFile(Uri u,String mode)throws FileNotFoundException{return ParcelFileDescriptor.open(png,ParcelFileDescriptor.MODE_READ_ONLY);}};android.content.pm.ProviderInfo providerInfo=new android.content.pm.ProviderInfo();providerInfo.authority="media";broken.attachInfo(context,providerInfo);ContentResolver failedResolver=ContentResolver.wrap(broken);Context failureContext=new ContextWrapper(context){@Override public ContentResolver getContentResolver(){return failedResolver;}};GalleryExport.Result ioFailure=GalleryExport.save(failureContext,List.of(p),new AtomicBoolean(),(a,b)->{});check(ioFailure.saved==0&&ioFailure.failed==1,"write IOException reported as failure");check(pending(context)==initialPending,"write failure removes pending row");
  File heic=new File(NativeBridge.received,prefix+".heic");files.add(heic);try(InputStream in=test.getContext().getAssets().open("gallery-check.heic");OutputStream out=new FileOutputStream(heic)){out.write(bytes(in));}GalleryExport.Photo h=GalleryExport.verified(NativeBridge.received,heic.getName());if(h!=null){check("image/heic".equals(h.mime),"decoder HEIF MIME normalized to HEIC without reencoding");GalleryExport.Result heif=GalleryExport.save(context,List.of(h),new AtomicBoolean(),(a,b)->{});created.add(heif.first);check(heif.saved==1&&heif.failed==0,"HEIC stored by supported platform");try(Cursor row=context.getContentResolver().query(heif.first,new String[]{MediaStore.MediaColumns.DISPLAY_NAME},null,null,null)){check(row!=null&&row.moveToFirst()&&heic.getName().equals(row.getString(0)),"HEIC extension preserved in gallery");}check(Arrays.equals(bytes(new FileInputStream(heic)),bytes(context.getContentResolver().openInputStream(heif.first))),"published HEIC bytes exact");}result.putBoolean("heicDecoderSupported",h!=null);
  if(Build.VERSION.SDK_INT>=33)check(context.checkSelfPermission("android.permission.READ_MEDIA_IMAGES")!=android.content.pm.PackageManager.PERMISSION_GRANTED,"no broad media permission required");
  result.putString("stream","FTA Gallery checks passed: "+checks+"; real decoder, MediaStore, exact bytes, collisions, cancellation, partial failure and recovery\n");resultCode=Activity.RESULT_OK;
 }catch(Throwable failure){result.putString("stream","FTA Gallery checks failed: "+failure.getClass().getSimpleName()+": "+failure.getMessage()+"\n");}finally{for(Uri uri:created)if(uri!=null)try{test.getTargetContext().getContentResolver().delete(uri,null,null);}catch(Exception ignored){}for(File file:files)file.delete();}test.finish(resultCode,result);}
}
